<?php
namespace App\Http\Controllers;

use App\Models\FuelType;
use App\Models\Nozzle;
use App\Models\ShiftType;
use App\Models\Station;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;

class SetupController extends Controller
{
    private function authorizeSetup(Request $request): void { abort_unless($request->user()->role==='Super Admin'||$request->user()->hasPermission('setup.manage'),403); }
    private function stationIds(Request $request){return $request->user()->role==='Super Admin'?Station::where('active',true)->pluck('id'):$request->user()->stations()->where('stations.active',true)->pluck('stations.id');}
    public function index(Request $request){$this->authorizeSetup($request);$ids=$this->stationIds($request);$stationId=$request->integer('station_id')?:$ids->first();abort_unless(!$stationId||$ids->contains($stationId),403);$stations=Station::whereIn('id',$ids)->orderBy('name')->get();$fuels=FuelType::orderBy('name')->get();$nozzles=Nozzle::with('fuelType')->whereIn('station_id',$ids)->when($stationId,fn($q)=>$q->where('station_id',$stationId))->orderBy('name')->get();$types=ShiftType::whereIn('station_id',$ids)->when($stationId,fn($q)=>$q->where('station_id',$stationId))->orderBy('starts_at')->get();return view('setup.index',compact('stations','stationId','fuels','nozzles','types'));}
    public function storeFuel(Request $request){$this->authorizeSetup($request);$data=$request->validate(['name'=>'required|string|max:50|unique:fuel_types,name','unit'=>'required|string|max:20','hsn_code'=>'nullable|string|max:30','tax_rate'=>'required|numeric|min:0|max:100']);FuelType::create([...$data,'active'=>true]);return back()->with('success','Fuel type added.');}
    public function updateFuel(Request $request,FuelType $fuel){$this->authorizeSetup($request);$data=$request->validate(['name'=>['required','string','max:50',Rule::unique('fuel_types','name')->ignore($fuel->id)],'unit'=>'required|string|max:20','hsn_code'=>'nullable|string|max:30','tax_rate'=>'required|numeric|min:0|max:100','active'=>'sometimes|boolean']);$fuel->update([...$data,'active'=>$request->boolean('active')]);return back()->with('success','Fuel type updated.');}
    public function storeNozzle(Request $request){$this->authorizeSetup($request);$data=$request->validate(['station_id'=>'required|integer|exists:stations,id','name'=>'required|string|max:80','fuel_type_id'=>'required|exists:fuel_types,id','dispenser'=>'nullable|string|max:80']);abort_unless($this->stationIds($request)->contains((int)$data['station_id']),403);$request->validate(['name'=>Rule::unique('nozzles','name')->where('station_id',$data['station_id'])]);$id=DB::transaction(function()use($data){$dispenserId=null;if(!empty($data['dispenser']))$dispenserId=DB::table('dispensers')->where('station_id',$data['station_id'])->where('name',$data['dispenser'])->value('id')??DB::table('dispensers')->insertGetId(['station_id'=>$data['station_id'],'name'=>$data['dispenser'],'created_at'=>now(),'updated_at'=>now()]);return Nozzle::create(['station_id'=>$data['station_id'],'name'=>$data['name'],'fuel_type_id'=>$data['fuel_type_id'],'dispenser_id'=>$dispenserId,'active'=>true])->id;});$this->audit($request,'nozzle_created','nozzle',$id,$data['station_id']);return back()->with('success','Nozzle added to the selected station.');}
    public function updateNozzle(Request $request,Nozzle $nozzle){$this->authorizeSetup($request);abort_unless($this->stationIds($request)->contains($nozzle->station_id),404);$data=$request->validate(['name'=>['required','string','max:80',Rule::unique('nozzles','name')->where('station_id',$nozzle->station_id)->ignore($nozzle->id)],'fuel_type_id'=>'required|exists:fuel_types,id','dispenser'=>'nullable|string|max:80','active'=>'sometimes|boolean']);if(!$request->boolean('active')&&$nozzle->active&&DB::table('shift_readings')->join('shifts','shifts.id','=','shift_readings.shift_id')->where('shift_readings.nozzle_id',$nozzle->id)->where('shifts.status','Open')->exists())return back()->withErrors(['active'=>'This nozzle is assigned to an open shift and cannot be deactivated.']);$dispenserId=null;if($data['dispenser'])$dispenserId=DB::table('dispensers')->where('station_id',$nozzle->station_id)->where('name',$data['dispenser'])->value('id')??DB::table('dispensers')->insertGetId(['station_id'=>$nozzle->station_id,'name'=>$data['dispenser'],'created_at'=>now(),'updated_at'=>now()]);$nozzle->update(['name'=>$data['name'],'fuel_type_id'=>$data['fuel_type_id'],'dispenser_id'=>$dispenserId,'active'=>$request->boolean('active')]);$this->audit($request,'nozzle_updated','nozzle',$nozzle->id,$nozzle->station_id);return back()->with('success','Nozzle settings updated.');}
    public function storeShiftType(Request $request){$this->authorizeSetup($request);$data=$request->validate(['station_id'=>'required|integer|exists:stations,id','name'=>'required|string|max:80','starts_at'=>'required|date_format:H:i','ends_at'=>'required|date_format:H:i']);abort_unless($this->stationIds($request)->contains((int)$data['station_id']),403);$request->validate(['name'=>Rule::unique('shift_types','name')->where('station_id',$data['station_id'])]);ShiftType::create([...$data,'active'=>true]);return back()->with('success','Shift type added.');}
    public function updateShiftType(Request $request,ShiftType $type){$this->authorizeSetup($request);abort_unless($this->stationIds($request)->contains($type->station_id),404);$data=$request->validate(['name'=>['required','string','max:80',Rule::unique('shift_types','name')->where('station_id',$type->station_id)->ignore($type->id)],'starts_at'=>'required|date_format:H:i','ends_at'=>'required|date_format:H:i','active'=>'sometimes|boolean']);$type->update([...$data,'active'=>$request->boolean('active')]);return back()->with('success','Shift type updated.');}
    private function audit(Request $request,string $action,string $entity,int $id,int $station):void{DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$station,'action'=>$action,'entity_type'=>$entity,'entity_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);}
}
